SELECT CASE WHEN cost >= 780 THEN 'high' WHEN cost >= 200 THEN 'mid' ELSE 'low' END AS cost_bucket, CASE WHEN stock_qty >= 359 THEN 'high' WHEN stock_qty >= 139 THEN 'mid' ELSE 'low' END AS stock_qty_bucket, MIN(launch_date) AS first_launch_date FROM products GROUP BY CASE WHEN cost >= 780 THEN 'high' WHEN cost >= 200 THEN 'mid' ELSE 'low' END, CASE WHEN stock_qty >= 359 THEN 'high' WHEN stock_qty >= 139 THEN 'mid' ELSE 'low' END
